scwin.vScrenID = 'ULDMGT80300.gfm';

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
};

scwin.onpageunload = function() {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.MxDataSet_OnLoadCompleted = function(e) {
    textbox_1.setValue("총 " + rowcount + "건");
};

scwin.btn_cal_onclick = function(e) {

    //----W-Craft WebSquare 변환 확인: popUpCalendar----//
    popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); //alert('image_2.onclick');

};

scwin.btn_sys_search_onclick = function(e) {
    if (txb_date.Text !== "") {
        scwin.listSync(); //alert();

    } else {
        alert("수신기준일자를 지정하십시요");
    }
};

scwin.image_1_onclick = function(e) {
    $c.data.downloadGridViewExcel(MxGrid_1, {fileName: "배포시스템_이용자제안", type: "2"});
};

// 일반 함수
/********************************************** 
 * 함수명   : Print()
 * 설명       : 화면을 인쇄한다. 
 ***********************************************/
scwin.print = function() {
    //alert(dts_UserList.text);

    //----W-Craft WebSquare 변환 확인: SetDataHeader----//
    dts_TempPrint.SetDataHeader("PROPS_ID:STRING(10), TITLE:STRING(200), PROPS_CONTN:STRING(2000), PROPSR_NM:STRING(80), PROPSR_EMAIL:STRING(100),PROPS_REG_DDTM:STRING(14)");
    dts_TempPrint.AddRow();
    dts_TempPrint.setNameValue(1, "PROPS_ID", PROPS_ID.value);
    dts_TempPrint.setNameValue(1, "TITLE", TITLE.value);
    dts_TempPrint.setNameValue(1, "PROPS_CONTN", PROPS_CONTN.value);
    dts_TempPrint.setNameValue(1, "PROPSR_NM", PROPSR_NM.value);
    dts_TempPrint.setNameValue(1, "PROPSR_EMAIL", PROPSR_EMAIL.value);
    dts_TempPrint.setNameValue(1, "PROPS_REG_DDTM", PROPS_REG_DDTM.value);

    //데이타셋 
    //var testDateSet = rex_gfGetGauceCsvStrAll(dts_TempPrint, MxDataSet_emp_data );

    //----W-Craft WebSquare 변환 확인: rex_gfGetGauceCsvStr----//
    const testDateSet = rex_gfGetGauceCsvStr(dts_TempPrint, MxDataSet);

    //Rexpert리포트 파일명 
    //var rex_rptname = "test/sample4";
    const rex_rptname = "ULDMGT70201";

    //Rexpert 미리보기 호출 
    scwin.openReport(testDateSet, rex_rptname);
};

//가우스데이타셋 연동 - 멀티 데이타셋
scwin.openReport = function(dataSetCSV, rex_rptname) {
    let oRptMainParam;

    //----W-Craft WebSquare 변환 확인: rex_GetgoDictionay----//
    oRptMainParam = rex_GetgoDictionay();

    // 필수 - 레포트명
    oRptMainParam.put("rex_rptname", rex_rptname);

    // 필수 - 데이터 타입 설정
    oRptMainParam.put("rex_datatype", "CSVSTR");
    oRptMainParam.put("rex_data", dataSetCSV);

    // 옵션 - 파라미터 정의
    const ab = PROPS_REG_DDTM.Text;
    const tx1 = ab.substring(0, 4);
    const tx2 = ab.substring(4, 6);
    const tx3 = ab.substring(6, 8);
    const tx4 = ab.substring(8, 10);
    const tx5 = ab.substring(10, 12);
    const tx6 = ab.substring(12, 14);
    const dtm = tx1 + "-" + tx2 + "-" + tx3 + " " + tx4 + ":" + tx5 + ":" + tx6;
    oRptMainParam.put("test_data", PROPS_ID.value);
    oRptMainParam.put("test_data1", TITLE.value);
    oRptMainParam.put("test_data2", PROPS_CONTN.Text);
    oRptMainParam.put("test_data3", PROPSR_NM.value);
    oRptMainParam.put("test_data4", PROPSR_EMAIL.value);
    oRptMainParam.put("test_data5", dtm);
    /*
dts_TempPrint.setNameValue(1, "PROPS_ID",PROPS_ID.value) 
dts_TempPrint.setNameValue(1, "TITLE",TITLE.value) 
dts_TempPrint.setNameValue(1, "PROPS_CONTN",PROPS_CONTN.value) 
dts_TempPrint.setNameValue(1, "PROPSR_NM",PROPSR_NM.value) 
dts_TempPrint.setNameValue(1, "PROPSR_EMAIL",PROPSR_EMAIL.value) 
dts_TempPrint.setNameValue(1, "PROPS_REG_DDTM",PROPS_REG_DDTM.value) 
			*/

    // 옵션 - 인쇄속성
    //oRptMainParam.put("rex_print", "direct=true;startpage=1;endpage=-1;count=1;skipzero=true");

    // 옵션 저장속성 
    //oRptMainParam.put("rex_save_file_type", "txt");
    //oRptMainParam.put("rex_save_file", "c:\Temp\aaa.txt");


    // 옵션 - 팝업설정
    //var rex_gsPreViewFeaturesCustom = "center=yes,scrollbars=no,status=no,toolbar=no,resizable=0,location=no,menu=no,width=825,height=768";
    //oRptMainParam.put("rex_open_window", rex_gsPreViewFeaturesCustom);
    const rex_gsPreViewFeaturesModalCustom = "center:yes;resizable__no;scroll:no;status:no;dialogWidth:825px;dialogHeight:768px";
    oRptMainParam.put("rex_open_window", rex_gsPreViewFeaturesModalCustom);

    // preview 팝업 열기
    //rex_gfRexRptOpen("popup", oRptMainParam);

    //----W-Craft WebSquare 변환 확인: rex_gfRexRptOpen----//
    rex_gfRexRptOpen("popupmodal", oRptMainParam);
};

scwin.listSync = function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/taskexeclog.do",
        ref : "",
        target : "MxDataSet=body.content",
        submitDoneHandler : scwin.MxDataSet_OnLoadCompleted,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


};

scwin.gform_onload = function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        submitDoneHandler : scwin.MxDataSet_OnLoadCompleted,
        isProcessMsg : false
    };

    $c.sbm.executeDynamic(sbmOptions);


    $c.cm.PanelToGroupBox_01(panel_1);
    $c.cm.PanelToGroupBox_02(panel_2);

    //----W-Craft WebSquare 변환 확인: toDaySet----//
    toDaySet(txb_date);
};
